<script setup>
import { onMounted, ref } from 'vue'
import { CheckCircle2, RefreshCw, RotateCcw, XCircle } from '@lucide/vue'
import api from '../api'
import LoadingSkeleton from './LoadingSkeleton.vue'
import { useUiStore } from '../stores/ui'
import { formatDateTime, money } from '../utils/format'

const ui = useUiStore(), loading = ref(true), error = ref(''), filter = ref(''), result = ref({items:[],total:0}), selected = ref(null), note = ref(''), submitting = ref(false)
const load = async () => { loading.value=true; error.value=''; try { result.value=await api.get(`/orders/admin/refunds?status=${filter.value}`) } catch(e){error.value=e.message} finally{loading.value=false} }
const openReview = (item, action) => { selected.value={item,action}; note.value='' }
const review = async () => { submitting.value=true; try { await api.post(`/orders/admin/refunds/${selected.value.item.refundNo}/review`,{action:selected.value.action,note:note.value}); ui.notify(selected.value.action==='APPROVE'?'退款已批准':'退款申请已驳回'); selected.value=null; await load() } catch(e){error.value=e.message;ui.notify(e.message,'error')} finally{submitting.value=false} }
onMounted(load)
</script>
<template><section class="admin-table-panel"><div class="admin-section-title"><div><p class="eyebrow dark">AFTER SALES</p><h2><RotateCcw :size="21"/>退款与售后</h2></div><span class="mono">{{ result.total }} 条申请</span></div><div class="admin-toolbar"><label>审核状态<select v-model="filter" @change="load"><option value="">全部状态</option><option value="PENDING">待审核</option><option value="APPROVED">已通过</option><option value="REJECTED">未通过</option></select></label><button class="icon-button light" type="button" aria-label="刷新退款申请" @click="load"><RefreshCw :size="18"/></button></div><div v-if="error" class="notice error">{{ error }}</div><LoadingSkeleton v-if="loading" :rows="3" compact/><div v-else class="table-scroll"><table class="control-table"><thead><tr><th>退款单</th><th>用户 / 订单</th><th>金额</th><th>原因</th><th>状态</th><th>申请时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in result.items" :key="item.refundNo"><td class="mono">{{ item.refundNo }}</td><td>{{ item.nickname || item.username }}<small class="mono">{{ item.orderNo }}</small></td><td class="mono">¥{{ money(item.totalAmount) }}</td><td>{{ item.reason }}<small v-if="item.adminNote">审核：{{ item.adminNote }}</small></td><td><span class="status" :class="item.status.toLowerCase()">{{ {PENDING:'待审核',APPROVED:'已通过',REJECTED:'未通过'}[item.status] }}</span></td><td>{{ formatDateTime(item.createdAt) }}</td><td><div v-if="item.status==='PENDING'" class="table-actions"><button class="icon-button light success-action" type="button" title="批准退款" aria-label="批准退款" @click="openReview(item,'APPROVE')"><CheckCircle2 :size="18"/></button><button class="icon-button light danger-action" type="button" title="驳回退款" aria-label="驳回退款" @click="openReview(item,'REJECT')"><XCircle :size="18"/></button></div><span v-else>已处理</span></td></tr></tbody></table></div><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><form class="dialog-panel" role="dialog" aria-modal="true" @submit.prevent="review"><p class="eyebrow dark">REFUND REVIEW</p><h2>{{ selected.action==='APPROVE'?'批准退款':'驳回申请' }}</h2><p class="mono">{{ selected.item.refundNo }}</p><label>审核说明<textarea v-model="note" rows="4" maxlength="300" required></textarea></label><div class="dialog-actions"><button class="button ghost" type="button" @click="selected=null">取消</button><button class="button primary" :disabled="submitting || !note.trim()">确认处理</button></div></form></div></section></template>
